using System.Text.Json;
namespace AgentSupervisor.Infrastructure;

public static class HookSecurity
{ private static readonly HashSet<string> Allowed = new(StringComparer.OrdinalIgnoreCase) { "SessionStart", "SessionEnd", "Stop", "PermissionRequest", "Notification" }; private static readonly string[] Secrets = { "token", "secret", "password", "authorization", "api_key", "apikey" }; public static bool IsAllowed(string? n) => n is not null && Allowed.Contains(n); public static string Redact(JsonElement e, int max = 65536) { var b = JsonSerializer.SerializeToUtf8Bytes(e); if (b.Length > max) return "{\"redacted\":\"payload-too-large\"}"; using var d = JsonDocument.Parse(b); return JsonSerializer.Serialize(R(d.RootElement)); } private static object? R(JsonElement e) => e.ValueKind switch { JsonValueKind.Object => e.EnumerateObject().ToDictionary(p => p.Name, p => Secrets.Any(s => p.Name.Contains(s, StringComparison.OrdinalIgnoreCase)) ? "[REDACTED]" : R(p.Value)), JsonValueKind.Array => e.EnumerateArray().Select(R).ToArray(), JsonValueKind.String => e.GetString(), JsonValueKind.Number => e.GetDecimal(), JsonValueKind.True => true, JsonValueKind.False => false, _ => null }; }
